<?php require 'config.php';admin_required();$rows=$pdo->query("SELECT l.*,b.title,u.name FROM loans l JOIN books b ON b.id=l.book_id JOIN users u ON u.id=l.user_id ORDER BY l.issued_at DESC")->fetchAll();$over=(int)$pdo->query("SELECT COUNT(*) FROM loans WHERE status='issued' AND due_date<CURDATE()")->fetchColumn();layout_start('Circulation reports');?><div class="stats"><article><small>Total loans</small><strong><?=count($rows)?></strong></article><article><small>Overdue loans</small><strong><?=$over?></strong></article><article><small>Returned</small><strong><?=$pdo->query("SELECT COUNT(*) FROM loans WHERE status='returned'")->fetchColumn()?></strong></article></div><section class="panel"><div class="panel-head"><h2>Loan history</h2><button onclick="window.print()">Print</button></div><div class="scroll"><table><tr><th>Book</th><th>Reader</th><th>Issued</th><th>Due</th><th>Returned</th><th>Status</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['title'])?></td><td><?=e($r['name'])?></td><td><?=e($r['issued_at'])?></td><td><?=e($r['due_date'])?></td><td><?=e($r['returned_at'])?></td><td><?=e($r['status'])?><?=($r['status']==='issued'&&$r['due_date']<date('Y-m-d'))?' · OVERDUE':''?></td></tr><?php endforeach;?></table></div></section><?php layout_end();?>